export interface ColumnInfo {
  name: string;
  type: string;
}

export interface TableInfo {
  name: string;
  columns: ColumnInfo[];
  rowCount: number;
}

export interface QueryResult {
  columns: string[];
  rows: Record<string, unknown>[];
  rowCount: number;
  executionTimeMs: number;
  resultType: 'table' | 'markdown';
}

export interface ToolCallResult {
  toolCallId: string;
  toolName?: string;
  sql: string;
  command?: string;
  toolInput?: Record<string, unknown>;
  columns: string[];
  rows: Record<string, unknown>[];
  rowCount: number;
  error?: string;
  output?: string;
  rawContent?: string;
  chart_spec?: {
    library?: 'plotly' | 'vegalite';
    data?: unknown[];
    layout?: Record<string, unknown>;
    frames?: unknown[];
    spec?: Record<string, unknown>;
  };
  answerDurationMs?: number;
}

export interface UserQuestionOption {
  label: string;
  description?: string;
}

export interface UserQuestionData {
  questionId: string;
  question: string;
  options: UserQuestionOption[];
  multiSelect: boolean;
}

export interface ContentSegment {
  type: 'thinking' | 'tool' | 'answer' | 'subagent_start' | 'subagent_end' | 'user_question' | 'error';
  text?: string;
  toolResult?: ToolCallResult;
  subagentId?: string;
  subagentName?: string;
  thinking?: string;
  sqlResults?: Array<{
    sql: string;
    columns?: string[];
    rows?: Record<string, unknown>[];
    rowCount?: number;
    error?: string;
  }>;
  chart_spec?: {
    library?: 'plotly' | 'vegalite';
    data?: unknown[];
    layout?: Record<string, unknown>;
    frames?: unknown[];
    spec?: Record<string, unknown>;
  };
  questionData?: UserQuestionData;
  userAnswer?: string[];
  userFreeText?: string;
  answerDurationMs?: number;
  errorMessage?: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  toolCalls?: ToolCallResult[];
  segments?: ContentSegment[];
  isStreaming?: boolean;
  currentPhase?: 'thinking' | 'answer';
  durationMs?: number;
}

export interface LangfuseStatus {
  enabled: boolean;
  dashboardUrl: string | null;
}

export interface SkillInfo {
  name: string;
  description: string;
  content?: string;
  builtin?: boolean;
  disabled?: boolean;
}

