255→      const legacySpec = data.chart_spec as ChartSpec | undefined;
256→      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);
257→
258→      const saThinking = (data.thinking as string) ?? undefined;
259→
260→      if (chartSpecs.length > 0) {
