169→function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
170→  const { t } = useTranslation();
171→  return (
172→    <div className="message-bubble__segment message-bubble__segment--error">
173→      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
174→      <div className="message-bubble__error-message">{errorMessage}</div>
175→      {onRetry && (
176→        <button className="message-bubble__error-retry" onClick={onRetry}>
177→          {t('tryAgain')}
178→        </button>
179→      )}
180→    </div>
181→  );
182→}
