184→function formatDuration(ms: number): string {
185→  if (ms < 1000) return '<1s';
186→  const seconds = Math.round(ms / 1000);
187→  if (seconds < 60) return `${seconds}s`;
188→  const minutes = Math.floor(seconds / 60);
189→  const remainingSeconds = seconds % 60;
190→  return remainingSeconds > 0 ? `${minutes}m ${remainingSeconds}s` : `${minutes}m`;
191→}
