193→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
194→  const { t } = useTranslation();
195→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
196→  const [isEditing, setIsEditing] = useState(false);
197→  const [editText, setEditText] = useState(message.content);
198→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
199→  const textareaRef = useRef<HTMLTextAreaElement>(null);
200→
201→  const isUser = message.role === 'user';
202→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
203→
204→  useEffect(() => {
205→    if (isEditing && textareaRef.current) {
206→      textareaRef.current.focus();
207→      textareaRef.current.selectionStart = textareaRef.current.value.length;
208→    }
209→  }, [isEditing]);
210→
211→  const handleEdit = () => {
212→    setEditText(message.content);
213→    setIsEditing(true);
214→    setIsConfirmingDelete(false);
215→  };
216→
217→  const handleCancelEdit = () => {
218→    setIsEditing(false);
219→    setEditText(message.content);
220→  };
221→
222→  const handleSaveEdit = () => {
223→    const trimmed = editText.trim();
224→    if (!trimmed || trimmed === message.content) {
225→      handleCancelEdit();
226→      return;
227→    }
228→    setIsEditing(false);
229→    editMessage(messageIndex, trimmed);
230→  };
231→
232→  const handleDeleteConfirm = () => {
233→    setIsConfirmingDelete(false);
234→    deleteMessage(messageIndex);
235→  };
236→
237→  const handleKeyDown = (e: React.KeyboardEvent) => {
238→    if (e.key === 'Escape') {
239→      handleCancelEdit();
240→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
241→      e.preventDefault();
242→      handleSaveEdit();
243→    }
244→  };
245→
246→  let streamingRemainder: string | undefined;
247→  if (hasSegments && message.isStreaming && message.content) {
248→    const segmentedText = message.segments!
249→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
250→      .map((s) => s.text || '')
251→      .join('');
252→    const remaining = message.content.slice(segmentedText.length);
253→    if (remaining.trim()) {
254→      streamingRemainder = remaining;
255→    }
256→  }
257→
258→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
259→  const isInAnswerPhase = message.currentPhase === 'answer';
260→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
261→
262→  const hasCharts = hasSegments && message.segments!.some(
263→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
264→  );
265→
266→  const answerBlockSegments = hasSegments
267→    ? message.segments!
268→        .filter((s) =>
269→          (s.type === 'answer' && s.text?.trim()) ||
270→          (s.type === 'subagent_end' && !s.chart_spec && !s.sqlResults?.length && s.text?.trim() && !hasAnswer) ||
271→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
272→          (s.type === 'subagent_end' && s.chart_spec)
273→        )
274→        .map((s) => {
275→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
276→            return { ...s, text: stripChartSpecBlocks(s.text) };
277→          }
278→          return s;
279→        })
280→        .filter((s) => {
281→          // Remove text segments that became empty after stripping chart blocks
282→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
283→            return false;
284→          }
285→          return true;
286→        })
287→    : [];
288→
289→  const questionSegments = hasSegments
290→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
291→    : [];
292→
293→  return (
294→    <div className={`message-bubble message-bubble--${message.role}`}>
295→      <div className="message-bubble__header">
296→        {isUser ? t('you') : t('assistant')}
297→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
298→          <span className="message-bubble__actions">
299→            <button
300→              className="message-bubble__action-btn"
301→              onClick={handleEdit}
302→              title={t('editMessage')}
303→            >
304→              &#9998;
305→            </button>
306→            <button
307→              className="message-bubble__action-btn message-bubble__action-btn--delete"
308→              onClick={() => setIsConfirmingDelete(true)}
309→              title={t('deleteMessage')}
310→            >
311→              &#128465;
312→            </button>
313→          </span>
314→        )}
315→      </div>
316→
317→      {isUser && isConfirmingDelete && (
318→        <div className="message-bubble__confirm-delete">
319→          <span>{t('deleteConfirm')}</span>
320→          <div className="message-bubble__confirm-actions">
321→            <button
322→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
323→              onClick={handleDeleteConfirm}
324→            >
325→              {t('delete')}
326→            </button>
327→            <button
328→              className="message-bubble__confirm-btn"
329→              onClick={() => setIsConfirmingDelete(false)}
330→            >
331→              {t('cancel')}
332→            </button>
333→          </div>
334→        </div>
335→      )}
336→
337→      {isUser && isEditing ? (
338→        <div className="message-bubble__edit-mode">
339→          <textarea
340→            ref={textareaRef}
341→            className="message-bubble__edit-textarea"
342→            value={editText}
343→            onChange={(e) => setEditText(e.target.value)}
344→            onKeyDown={handleKeyDown}
345→            rows={3}
346→          />
347→          <div className="message-bubble__edit-actions">
348→            <button
349→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
350→              onClick={handleSaveEdit}
351→            >
352→              {t('saveResend')}
353→            </button>
354→            <button
355→              className="message-bubble__edit-btn"
356→              onClick={handleCancelEdit}
357→            >
358→              {t('cancel')}
359→            </button>
360→          </div>
361→        </div>
362→      ) : hasSegments ? (
363→        <div className="message-bubble__segments">
364→          {!questionSegments.some((s) => !s.userAnswer) && (
365→            <ThinkingBlock
366→              segments={message.segments!}
367→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
368→              isThinkingPhase={isThinkingPhase}
369→              isAgentStreaming={!!message.isStreaming}
370→              hasAnswer={hasAnswer}
371→            />
372→          )}
373→          {questionSegments.map((seg, i) => (
374→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
375→              <UserQuestion
376→                questionData={seg.questionData!}
377→                userAnswer={seg.userAnswer}
378→                userFreeText={seg.userFreeText}
379→                answerDurationMs={seg.answerDurationMs}
380→              />
381→            </div>
382→          ))}
383→          {answerBlockSegments.length > 0 && (
384→            <div className="message-bubble__segment message-bubble__segment--answer">
385→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
386→              {answerBlockSegments.map((seg, i) => {
387→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
388→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
389→                  return (
390→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
391→                      {seg.type === 'tool' && seg.toolResult ? (
392→                        <InlineQueryResult result={seg.toolResult!} />
393→                      ) : seg.chart_spec ? (
394→                        seg.chart_spec.library === 'vegalite' && seg.chart_spec.spec
395→                          ? <VegaLiteChartWidget spec={seg.chart_spec.spec} />
396→                          : <ChartWidget data={seg.chart_spec.data ?? []} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
397→                      ) : null}
398→                    </div>
399→                  );
400→                }
401→                // Text segment (answer or subagent_end without chart_spec)
402→                return (
403→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
404→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(seg.text!)}</ReactMarkdown>
405→                  </div>
406→                );
407→              })}
408→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
409→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
410→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
411→                return displayText?.trim() ? (
412→                  <div className="message-bubble__segment-content">
413→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
414→                  </div>
415→                ) : null;
416→              })()}
417→              {!message.isStreaming && message.durationMs != null && (
418→                <div className="message-bubble__duration">
419→                  {t('answeredIn', { time: formatDuration(message.durationMs) })}
420→                </div>
421→              )}
422→            </div>
423→          )}
424→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
425→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
426→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
427→            return displayText?.trim() ? (
428→              <div className="message-bubble__segment message-bubble__segment--answer">
429→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
430→                <div className="message-bubble__segment-content">
431→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
432→                </div>
433→              </div>
434→            ) : null;
435→          })()}
436→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
437→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
438→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
439→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
440→          })}
441→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
442→            <span className="message-bubble__typing">{t('thinking')}</span>
443→          )}
444→        </div>
445→      ) : (
446→        <>
447→          <div className="message-bubble__content">
448→            {message.content ? (
449→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(message.content)}</ReactMarkdown>
450→            ) : message.isStreaming ? (
451→              <span className="message-bubble__typing">{t('thinking')}</span>
452→            ) : null}
453→          </div>
454→          {message.toolCalls && message.toolCalls.length > 0 && (
455→            <div className="message-bubble__tools">
456→              {message.toolCalls.map((tc) => (
457→                <InlineQueryResult key={tc.toolCallId} result={tc} />
458→              ))}
459→            </div>
