818→          method: 'POST',
819→          headers: {
820→            'Content-Type': 'application/json',
821→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
822→          },
823→          body: JSON.stringify({
824→            question_id: questionId,
825→            answers,
826→            free_text: freeText || null,
827→          }),
828→        });
829→      } catch (e) {
830→        console.error('Failed to respond to question:', e);
831→      }
832→    },
833→    [userSessionId]
834→  );
835→
836→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
837→    const outgoing = outgoingConversationId || null;
838→    const incoming = incomingConversationId || null;
839→    activeConversationIdRef.current = incoming;
840→
841→    // Save outgoing conversation's messages to cache (only if not streaming --
842→    // streaming conversations keep their state in streamStatesRef)
843→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
844→      const currentMsgs = messagesRef.current;
845→      if (currentMsgs.length > 0) {
846→        messagesCacheRef.current.set(outgoing, currentMsgs);
847→      }
848→    }
849→
850→    // Check if incoming conversation has an active stream (re-attachment)
851→    if (incoming) {
852→      const streamState = streamStatesRef.current.get(incoming);
853→      if (streamState) {
854→        // Re-attach: use live stream messages
855→        setMessages(streamState.messages);
856→        setIsStreaming(true);
857→        return;
858→      }
859→    }
860→
861→    // No active stream -- use backend data or cache
862→    let finalMsgs = msgs;
863→    if (incoming) {
864→      const cached = messagesCacheRef.current.get(incoming);
865→      if (cached && cached.length > 0 && cached.length > msgs.length) {
866→        finalMsgs = cached;
867→      }
868→      messagesCacheRef.current.delete(incoming);
869→    }
870→
871→    setMessages(finalMsgs);
872→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
873→    setIsStreaming(hasStreamingMsg);
874→    sessionIdRef.current = null;
875→    pendingHistoryRef.current = null;
876→  }, []);
877→
878→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
879→    const outgoing = outgoingConversationId || null;
880→    activeConversationIdRef.current = null;
881→
882→    // Save outgoing messages to cache if not streaming
883→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
884→      const currentMsgs = messagesRef.current;
885→      if (currentMsgs.length > 0) {
886→        messagesCacheRef.current.set(outgoing, currentMsgs);
887→      }
888→    }
889→
890→    setMessages([]);
891→    setIsStreaming(false);
892→    sessionIdRef.current = null;
893→    pendingHistoryRef.current = null;
894→  }, []);
895→
896→  return (
897→    <AgentContext.Provider
898→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
899→    >
900→      {children}
901→    </AgentContext.Provider>
902→  );
903→}
