  const startSeg = [...state.segments].reverse().find(
    s => s.type === 'subagent_start' && s.subagentId === data.id
  );
  if (startSeg) {
    startSeg.thinking = (startSeg.thinking ?? '') + data.text;
    updateMessages(msgs =>
